{
  "name": "Keysight N9020B MXA信号分析仪",
  "name_en": "Keysight N9020B MXA Signal Analyzer",
  "manufacturer": "Keysight Technologies",
  "description": "这是一台台式射频/微波信号分析仪，可在频谱分析模式下测量信号的频率分布、功率电平和峰值位置。它常用于实验室中的射频链路调试、信号源与放大器表征、杂散与谐波观察，以及频谱扫描和标记测量。",
  "description_en": "This is a benchtop RF/microwave signal analyzer used in spectrum analysis mode to measure signal frequency distribution, power level, and peak locations. It is commonly used in laboratories for RF chain debugging, source and amplifier characterization, spurious and harmonic observation, spectrum sweeps, and marker-based measurements.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭与仪器的连接。",
      "description_en": "Close the connection to the instrument."
    },
    {
      "action_name": "auto-query_mark_delta_x",
      "description": "读取指定标记的频率差值。",
      "description_en": "Read the frequency delta of the selected marker."
    },
    {
      "action_name": "auto-query_mark_x_freq",
      "description": "读取指定标记的频率位置。",
      "description_en": "Read the frequency position of the selected marker."
    },
    {
      "action_name": "auto-query_mark_y_power",
      "description": "读取当前标记处的功率电平。",
      "description_en": "Read the power level at the current marker."
    },
    {
      "action_name": "auto-save_png",
      "description": "保存频谱截图和测量数据文件。",
      "description_en": "Save a spectrum screenshot and measurement data files."
    },
    {
      "action_name": "auto-set_auto_tune",
      "description": "自动调整参考电平。",
      "description_en": "Automatically adjust the reference level."
    },
    {
      "action_name": "auto-set_cal_all",
      "description": "执行整机自校准。",
      "description_en": "Run full self-calibration."
    },
    {
      "action_name": "auto-set_cont",
      "description": "设置为连续扫描模式。",
      "description_en": "Set the analyzer to continuous sweep mode."
    },
    {
      "action_name": "auto-set_freq",
      "description": "设置测量频率。",
      "description_en": "Set the measurement frequency."
    },
    {
      "action_name": "auto-set_freq_cent",
      "description": "设置中心频率。",
      "description_en": "Set the center frequency."
    },
    {
      "action_name": "auto-set_freq_span",
      "description": "设置频谱跨度。",
      "description_en": "Set the frequency span."
    },
    {
      "action_name": "auto-set_freq_span_max",
      "description": "将频谱跨度设为最大。",
      "description_en": "Set the frequency span to the maximum."
    },
    {
      "action_name": "auto-set_freq_start",
      "description": "设置起始频率。",
      "description_en": "Set the start frequency."
    },
    {
      "action_name": "auto-set_freq_stop",
      "description": "设置终止频率。",
      "description_en": "Set the stop frequency."
    },
    {
      "action_name": "auto-set_mark_all_off",
      "description": "关闭所有标记。",
      "description_en": "Turn off all markers."
    },
    {
      "action_name": "auto-set_mark_del_freq",
      "description": "设置指定差分标记的频率偏移。",
      "description_en": "Set the frequency offset for the selected delta marker."
    },
    {
      "action_name": "auto-set_mark_delt_on",
      "description": "开启差分标记功能。",
      "description_en": "Enable delta marker mode."
    },
    {
      "action_name": "auto-set_mark_to_cf",
      "description": "将指定标记位置设为中心频率。",
      "description_en": "Set the selected marker position as the center frequency."
    },
    {
      "action_name": "auto-set_marker_freq",
      "description": "设置指定标记的频率位置。",
      "description_en": "Set the frequency position of the selected marker."
    },
    {
      "action_name": "auto-set_mode_spectrum_analyzer",
      "description": "切换到频谱分析模式。",
      "description_en": "Switch to spectrum analyzer mode."
    },
    {
      "action_name": "auto-set_next_peak",
      "description": "跳转到下一个峰值。",
      "description_en": "Move to the next peak."
    },
    {
      "action_name": "auto-set_peak_search",
      "description": "执行峰值搜索。",
      "description_en": "Perform a peak search."
    },
    {
      "action_name": "auto-set_peak_search_continuous_on",
      "description": "开启连续峰值搜索。",
      "description_en": "Enable continuous peak search."
    },
    {
      "action_name": "auto-set_rbw",
      "description": "设置分辨带宽。",
      "description_en": "Set the resolution bandwidth."
    },
    {
      "action_name": "auto-set_rbw_auto",
      "description": "启用分辨带宽自动设置。",
      "description_en": "Enable automatic resolution bandwidth."
    },
    {
      "action_name": "auto-set_ref_level",
      "description": "设置参考电平。",
      "description_en": "Set the reference level."
    },
    {
      "action_name": "auto-set_single",
      "description": "设置为单次扫描模式。",
      "description_en": "Set the analyzer to single sweep mode."
    },
    {
      "action_name": "auto-set_vbw",
      "description": "设置视频带宽。",
      "description_en": "Set the video bandwidth."
    },
    {
      "action_name": "auto-set_vbw_auto",
      "description": "启用视频带宽自动设置。",
      "description_en": "Enable automatic video bandwidth."
    }
  ],
  "tag_hints": [
    "RF spectrum analysis",
    "microwave measurements",
    "signal analyzer",
    "marker peak search",
    "RBW/VBW control",
    "frequency span sweep",
    "reference level setting"
  ]
}

